@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700&display=swap');
:root{--bg:#090d12;--panel:#10171e;--panel2:#141d26;--line:rgba(196,218,232,.12);--text:#e9f1f5;--muted:#82919e;--gold:#e4bd76;--cyan:#73d8df;--red:#f07876;--green:#80d2a4;--mono:'DM Mono',monospace;--sans:'Manrope',sans-serif;--serif:'Playfair Display',serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(ellipse at 50% -20%,#26333a 0,transparent 58%),linear-gradient(180deg,#0b1015,#090d12 65%)}button{font:inherit;color:inherit;cursor:pointer}#app{max-width:1600px;margin:auto;padding:21px 30px 26px}.topbar{height:55px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);margin-bottom:20px}.brand{display:flex;align-items:center;gap:12px;letter-spacing:.22em;font-size:12px;font-weight:800}.sigil{width:26px;height:26px;border:1px solid var(--gold);transform:rotate(45deg);display:grid;place-items:center;color:var(--gold);font-size:12px}.sigil span{transform:rotate(-45deg)}.brand small{color:#71818c;font:10px var(--mono);letter-spacing:.15em;margin-left:5px}.top-right{display:flex;gap:23px;align-items:center;font:10px var(--mono);letter-spacing:.12em;color:var(--muted)}.live{color:var(--green)}.live:before{content:'';display:inline-block;width:6px;height:6px;background:var(--green);border-radius:50%;margin-right:8px;box-shadow:0 0 10px var(--green)}.icon-btn{background:transparent;border:1px solid var(--line);border-radius:50%;width:30px;height:30px;color:var(--gold)}
.layout{display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:19px}.maincol{min-width:0}.level-head{display:flex;align-items:flex-end;justify-content:space-between;padding:1px 2px 13px}.eyebrow{font:10px var(--mono);letter-spacing:.14em;color:#83929c}.eyebrow span{color:#485660;margin:0 5px}.eyebrow b{font-weight:400;color:var(--gold)}h1{font:600 36px var(--serif);margin:7px 0 0;letter-spacing:.01em}h1 i{font:12px var(--mono);color:#6e7c86;margin-left:8px;font-style:normal}.floor-state{font:9px var(--mono);letter-spacing:.12em;color:#a8b7bd;padding-bottom:7px}.status-dot{width:6px;height:6px;display:inline-block;border-radius:50%;background:var(--green);margin:0 8px 1px 0;box-shadow:0 0 8px var(--green)}
.scene-wrap{height:clamp(300px,38vw,460px);min-height:300px;position:relative;overflow:hidden;border:1px solid rgba(202,225,230,.16);background:#101a20;box-shadow:0 15px 50px #0007}.scene-wrap:after{content:'';pointer-events:none;position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,13,16,.22),transparent 30%,transparent 72%,rgba(8,13,16,.22)),linear-gradient(0deg,rgba(7,11,14,.32),transparent 35%,rgba(8,12,16,.2));}.scene-wrap canvas{display:block;width:100%;height:100%}.scene-top{position:absolute;top:17px;left:18px;right:18px;display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.15em;color:#9eabb0;pointer-events:none}.scene-tag{background:rgba(9,15,19,.6);padding:9px 11px;border:1px solid #ffffff1a;color:#c5d0d1}.scene-tag i{font-style:normal;color:var(--gold);margin-right:6px}.scene-bottom{position:absolute;bottom:19px;left:21px;right:21px;display:flex;align-items:end;justify-content:space-between;pointer-events:none}.scene-bottom strong{display:block;font:600 16px var(--serif);letter-spacing:.08em}.scene-bottom small{display:block;margin-top:5px;font:9px var(--mono);color:#b4c0c3;letter-spacing:.13em}.enemy-health{width:33%;max-width:245px}.barline,.vital-label,.level-line{display:flex;justify-content:space-between;align-items:center;font:9px var(--mono);letter-spacing:.08em;color:#a5b2b7;margin-bottom:6px}.barline span:last-child{color:#d8e1e2}.bar{height:5px;background:#ffffff20;overflow:hidden;position:relative}.bar i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#ae5a57,#ec8176);transition:width .25s ease;box-shadow:0 0 10px #ed766773}.toast{position:absolute;left:50%;top:48%;transform:translate(-50%,-50%);font:500 13px var(--mono);letter-spacing:.16em;color:#fff4d7;text-shadow:0 2px 15px #e4bd76;opacity:0;pointer-events:none;transition:opacity .2s;white-space:nowrap;z-index:2}.toast.show{opacity:1}.combat-row{height:73px;display:flex;align-items:center;justify-content:space-between}.hero-vitals{display:flex;align-items:center;gap:12px;width:280px}.portrait{position:relative;width:38px;height:38px;border:1px solid #b69e6c6b;background:linear-gradient(140deg,#29353b,#141a1e);display:grid;place-items:center;color:var(--gold);font-size:18px}.portrait span{position:absolute;bottom:-5px;right:-5px;padding:2px 3px;background:#1d252a;font:8px var(--mono);color:#eee;border:1px solid #424e50}.vital-stack{flex:1}.vital-label{margin-bottom:4px;font-size:8px;color:#95a3a9}.vital-label b{color:#dce5e6;font-weight:400}.bar.hp,.bar.mp{height:3px;margin-bottom:7px;background:#ffffff15}.bar.hp i{background:linear-gradient(90deg,#b55554,#e27b70)}.bar.mp i{background:linear-gradient(90deg,#487fb0,#79c3db);box-shadow:0 0 9px #79c3db6b}.mana-label{margin-top:0}.combat-note{font:9px var(--mono);letter-spacing:.08em;color:#84939c}.keycap,kbd{font:8px var(--mono);border:1px solid #53616a;padding:3px 4px;color:#c1ced1;background:#111a20}.sep{margin:0 7px;color:#65737c}
.actions{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.action{height:62px;background:linear-gradient(130deg,#141c22,#11181e);border:1px solid #ffffff18;display:flex;align-items:center;text-align:left;gap:11px;padding:0 13px;position:relative;transition:.18s;overflow:hidden}.action:hover:not(:disabled){transform:translateY(-2px);border-color:#e4bd766b;background:#1b252b}.action:active:not(:disabled){transform:translateY(0)}.action:disabled{opacity:.42;cursor:not-allowed}.action.primary{border-color:#b596596b;background:linear-gradient(120deg,#30281c,#171c1e)}.action-icon{font-size:21px;color:var(--gold);width:24px;text-align:center}.skill .action-icon{color:#8ac8df}.evade .action-icon{color:#9bc9ac}.potion .action-icon{color:#cf8b80}.action b{display:block;font:600 9px var(--mono);letter-spacing:.1em;white-space:nowrap}.action small{display:block;font:8px var(--mono);color:#839198;margin-top:5px;letter-spacing:.035em;white-space:nowrap}.action kbd{font-size:7px;padding:2px 3px;margin-left:3px}.cooldown{position:absolute;left:0;bottom:0;height:2px;background:var(--gold);width:0;transition:width .12s}.log-wrap{margin-top:18px;border-top:1px solid var(--line);padding-top:13px}.section-title,.panel-title{font:9px var(--mono);letter-spacing:.13em;color:#acb9be;display:flex;justify-content:space-between;align-items:center}.section-title span{font-size:8px;color:#56646c}.combat-log{height:61px;overflow:hidden;display:flex;flex-direction:column-reverse;padding-top:6px;gap:4px}.log-entry{font:10px var(--mono);color:#87959c;animation:appear .24s}.log-entry b{font-weight:400;color:#d9e3e3}.log-entry .damage{color:#e8877b}.log-entry .good{color:#9bd5ab}.log-entry .gold{color:var(--gold)}@keyframes appear{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
.sidebar{display:flex;flex-direction:column;gap:11px}.panel{background:linear-gradient(145deg,rgba(21,30,37,.96),rgba(15,22,28,.96));border:1px solid var(--line);padding:15px 16px;box-shadow:0 8px 24px #0002}.panel-title{padding-bottom:12px;border-bottom:1px solid #ffffff0f}.more{letter-spacing:.2em;color:#72808a}.profile-main{display:flex;align-items:center;gap:12px;padding:14px 0 12px}.avatar{height:42px;width:42px;display:grid;place-items:center;border:1px solid #d5b66e55;background:radial-gradient(circle,#34342d,#1a2023);color:#e1c47f;font-size:20px;box-shadow:inset 0 0 16px #dbbd4b0d}.profile-main h2{font:600 15px var(--serif);margin:0 0 5px}.rank{font:8px var(--mono);letter-spacing:.06em;color:#a9b5b9}.rank span{color:var(--gold);margin-right:4px}.level-line{font-size:8px;color:#9eacb1;margin:2px 0 6px}.level-line b{color:#ead098;font-weight:500;margin-left:5px}.bar.xp{height:3px;background:#ffffff16}.bar.xp i{background:linear-gradient(90deg,#bb9a5c,#efcf86);box-shadow:0 0 8px #d5ae5d66;display:block;height:100%;width:0;transition:width .3s}.stats{display:grid;grid-template-columns:repeat(4,1fr);margin:14px -2px 0;padding-top:11px;border-top:1px solid #ffffff10}.stats div{display:flex;flex-direction:column;gap:4px;border-right:1px solid #ffffff10;padding-left:9px}.stats div:first-child{padding-left:0}.stats div:last-child{border:0}.stats small{font:7px var(--mono);color:#73828a;letter-spacing:.06em}.stats b{font:13px var(--mono);font-weight:400;color:#dce5e5}.allocate{margin-top:12px;width:100%;border:1px solid #c9a95a66;color:var(--gold);background:#b18b3512;padding:8px;font:9px var(--mono);letter-spacing:.12em}.allocate:hover{background:#b18b3530}.hidden{display:none!important}.quest-mark{color:var(--gold);font-size:14px}.quest{display:flex;gap:10px;padding:14px 0 10px}.quest-icon{width:32px;height:32px;display:grid;place-items:center;color:#ddbd73;background:#c9a45112;border:1px solid #d2ae4f2b}.quest b{font:600 11px var(--sans);color:#dce4e5}.quest p{font-size:9px;color:#87959b;margin:4px 0 0;line-height:1.55}.quest-progress{display:flex;align-items:center;gap:10px;font:8px var(--mono);color:#a7b3b7}.quest-progress .bar{flex:1;height:3px}.quest-progress .bar i{height:100%;width:0;display:block;background:var(--gold);transition:width .2s}.reward{margin-top:12px;padding-top:10px;border-top:1px solid #ffffff10;display:flex;justify-content:space-between;font:8px var(--mono);color:#77858d;letter-spacing:.05em}.reward b{color:#d8c38b;font-weight:400}.reward i{color:#69767c;font-style:normal}.tower-visual{margin-top:11px;height:91px;background:linear-gradient(90deg,#121d24,#18232a);border:1px solid #ffffff0d;display:flex;align-items:center;position:relative;overflow:hidden;padding-left:12px}.tower-visual:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent 0%,rgba(18,26,30,.08) 40%,#141c22 83%)}.tower-silhouette{width:46px;height:76px;position:relative;display:flex;flex-direction:column;justify-content:space-evenly;align-items:center;filter:drop-shadow(0 0 7px #c59e3c33)}.tower-silhouette:before{content:'';position:absolute;bottom:0;left:10px;right:10px;height:100%;background:linear-gradient(90deg,#202a2d,#313a39,#1c2629);clip-path:polygon(35% 0,65% 0,65% 9%,82% 9%,82% 20%,73% 20%,73% 34%,88% 34%,88% 46%,76% 46%,76% 64%,94% 64%,94% 100%,6% 100%,6% 64%,24% 64%,24% 46%,12% 46%,12% 34%,27% 34%,27% 20%,18% 20%,18% 9%,35% 9%)}.tower-silhouette i{z-index:1;display:block;width:3px;height:2px;background:#d6b658;box-shadow:0 0 5px #d6b658}.tower-copy{z-index:1;margin-left:13px;display:flex;flex-direction:column}.tower-copy b{font:25px var(--serif);color:#e9d39c}.tower-copy small{font:7px var(--mono);letter-spacing:.1em;color:#8e9ba1}.tower-copy span{font:7px var(--mono);letter-spacing:.09em;color:#b29258;margin-top:7px}.floor-list{height:21px;display:flex;gap:4px;margin-top:10px}.floor-list i{height:3px;flex:1;background:#ffffff15}.floor-list i.done{background:#cfaa5e}.floor-list i.current{background:#f3d37e;box-shadow:0 0 6px #f3d37e}.gold-text{color:#d5b46d;font-size:9px}.gear-row{display:flex;align-items:center;gap:10px;padding-top:11px}.gear-icon{height:29px;width:29px;display:grid;place-items:center;border:1px solid #ffffff12;background:#ffffff08;color:#d6bd80;font-size:15px}.gear-icon.armor{color:#8fb4c0}.gear-row b{display:block;font-size:9px;font-weight:600}.gear-row small{display:block;color:#8a989f;font:8px var(--mono);margin-top:3px}.gear-slot{margin-left:auto;font:7px var(--mono);letter-spacing:.1em;color:#69777e}.continue{height:43px;background:linear-gradient(100deg,#d1ae65,#9d804a);border:0;color:#14181a;font:700 10px var(--mono);letter-spacing:.12em;display:flex;align-items:center;justify-content:space-between;padding:0 15px;box-shadow:0 4px 18px #c39b4525}.continue:hover{filter:brightness(1.13);transform:translateY(-1px)}.footnote{display:flex;justify-content:space-between;color:#58666e;font:7px var(--mono);letter-spacing:.07em;padding:2px 2px}.modal{position:fixed;inset:0;background:#05090cbb;backdrop-filter:blur(8px);z-index:10;display:grid;place-items:center;padding:20px}.modal-card{max-width:410px;width:100%;text-align:center;padding:38px 35px;background:linear-gradient(145deg,#19242a,#10171d);border:1px solid #d1b16555;box-shadow:0 25px 100px #0009}.modal-sigil{font-size:34px;color:var(--gold);margin-bottom:15px;text-shadow:0 0 20px #debb6477}.modal-card h2{font:600 28px var(--serif);margin:10px 0}.modal-card p{color:#9eacb1;font-size:12px;line-height:1.8;margin:0 auto 24px}.modal-card button{background:var(--gold);color:#11181c;border:0;padding:13px 20px;font:700 9px var(--mono);letter-spacing:.1em}.shake{animation:shake .3s}@keyframes shake{25%{transform:translateX(-6px)}75%{transform:translateX(6px)}}
@media(max-width:1000px){#app{padding:16px 18px}.layout{grid-template-columns:minmax(0,1fr) 285px;gap:13px}.action{padding:0 8px;gap:7px}.action b{font-size:8px}.action small{font-size:7px}.panel{padding:13px}.combat-note{font-size:8px}}
@media(max-width:760px){#app{padding:10px 12px 20px}.topbar{height:46px;margin-bottom:13px}.brand{font-size:10px;gap:9px}.brand small{font-size:8px}.top-right{gap:10px;font-size:8px}.layout{display:flex;flex-direction:column}.level-head{padding-bottom:10px}h1{font-size:30px}.eyebrow{font-size:8px}.scene-wrap{height:clamp(290px,62vw,430px);min-height:290px}.scene-bottom{left:13px;right:13px;bottom:14px}.scene-bottom strong{font-size:13px}.enemy-health{width:40%}.combat-row{height:65px}.hero-vitals{width:52%;gap:9px}.combat-note{font-size:0}.combat-note .keycap{font-size:8px}.combat-note .sep{font-size:9px;margin:0 4px}.actions{grid-template-columns:repeat(2,1fr);gap:7px}.action{height:57px;padding:0 12px}.action b{font-size:9px}.action small{font-size:8px}.sidebar{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-top:5px}.profile,.objective{grid-row:span 1}.tower,.inventory{align-self:start}.continue,.footnote{grid-column:1/-1}.panel{padding:12px}.tower-visual{height:80px}.floor-list{margin-top:7px}.footnote{font-size:7px}}
@media(max-width:420px){.top-right #clock{display:none}.scene-wrap{height:300px}.combat-note{max-width:145px;text-align:right;line-height:2}.actions{gap:6px}.action{height:54px;padding:0 8px;gap:6px}.action-icon{font-size:18px;width:20px}.action b{font-size:8px}.action small{font-size:7px}.sidebar{grid-template-columns:1fr}.profile,.objective,.tower,.inventory{grid-column:1}.profile{grid-row:auto}.tower-visual{height:83px}.floor-state{font-size:8px}.enemy-health{width:43%}}

(()=>{'use strict';
const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d');
const themes=[['THE FORGOTTEN HALL','ASHFALL','HOLLOW SENTINEL','a drowned knight'],['VERDANT RUINS','MIST VEIL','THORN STALKER','a thornbound wraith'],['THE SUNKEN ARCHIVE','BLUE HAZE','DUSK WRAITH','a shadow wraith'],['OBSIDIAN DEPTHS','EMBERFALL','CINDER HOUND','an ember hound'],['THE PALE GARDEN','MOON DUST','PALE DUELIST','a pale duelist'],['SKYWARD SANCTUM','STARFALL','ASTRAL KNIGHT','an astral knight'],['THE HOLLOW CROWN','BLACK SNOW','VOID REVENANT','a void revenant'],['THE ECLIPSE GATE','ECLIPSE','NIGHTMARE','a nightmare'],['CELESTIAL VAULT','STARDUST','FALLEN SERAPH','a fallen seraph'],['THE THRONE ABOVE','AETHER RAIN','TOWER WARDEN','the Tower Warden']];
const bossNames=['VORATH, THE GATEKEEPER','THE WIDOW OF THORNS','ARCHIVIST NOX','PYRE, THE ASHEN KING','THE PALE EMPRESS','SERAPHIEL, STARBORN','MALGRAVE THE UNDYING','THE ECLIPSE SHADE','AZRIEL, LAST OF THE HOST','THE CROWNLESS KING'];
const initial={floor:1,level:1,xp:0,hp:100,mp:50,gold:50,potions:3,kills:0,str:10,agi:10,vit:10,int:10,points:0,unlocked:1,weapon:0,won:false};
let s={...initial};try{const saved=JSON.parse(localStorage.getItem('ascendant-save'));if(saved)s={...initial,...saved}}catch(e){}
let enemy,fx=[],logEntries=[],now=0,last=0,attackCd=0,skillCd=0,dodgeCd=0,invuln=0,playerAnim=0,enemyAnim=0,shake=0,combatState='fight',soundOn=false,audio;
const pickTheme=()=>themes[Math.floor((s.floor-1)/10)%10];
function isBoss(f=s.floor){return f%10===0||f===100}
function makeEnemy(){let f=s.floor,t=pickTheme(),boss=isBoss(f),base=95+f*22+Math.floor(f/10)*35;enemy={name:boss?bossNames[Math.ceil(f/10)-1]:t[2],hp:base,max:base,atk:5+f*1.6,level:f,boss,attackTimer:2.1+Math.random()*1.8,windup:0,stun:0,flash:0,phase:0}}
function persist(){try{localStorage.setItem('ascendant-save',JSON.stringify(s))}catch(e){}}
function xpNeed(){return 100+(s.level-1)*65}
function log(text,kind=''){let d=document.createElement('div');d.className='log-entry';d.innerHTML=text; if(kind)d.classList.add(kind);$('combatLog').prepend(d);while($('combatLog').children.length>5)$('combatLog').lastChild.remove()}
function toast(text){let el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),900)}
function audioHit(freq=180){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=freq;o.type='sawtooth';g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);o.start();o.stop(audio.currentTime+.12)}catch(e){}}
function updateUI(){let t=pickTheme();$('floorNum').textContent=String(s.floor).padStart(2,'0');$('towerFloor').textContent=String(s.floor).padStart(2,'0');$('towerProgress').textContent=`${s.floor}%`;$('towerLabel').textContent=s.floor<=10?'THE LOWER SPIRE':s.floor<=30?'THE MIDDLE SPIRE':s.floor<=60?'THE UPPER SPIRE':'THE SUMMIT';$('zoneName').textContent=t[0];$('weather').textContent=`${t[1]} · ${String(3+Math.floor(now/60)%9).padStart(2,'0')}:${String(Math.floor(now)%60).padStart(2,'0')}`;
$('levelText').textContent=String(s.level).padStart(2,'0');$('portraitLevel').textContent=String(s.level).padStart(2,'0');$('strStat').textContent=s.str;$('agiStat').textContent=s.agi;$('vitStat').textContent=s.vit;$('intStat').textContent=s.int;$('pointsText').textContent=s.points;$('allocateBtn').classList.toggle('hidden',!s.points);$('xpText').textContent=`${s.xp} / ${xpNeed()} XP`;$('xpBar').style.width=`${Math.min(100,s.xp/xpNeed()*100)}%`;
$('hpText').textContent=`${Math.ceil(s.hp)} / ${100+(s.vit-10)*8}`;$('hpBar').style.width=`${Math.max(0,s.hp/(100+(s.vit-10)*8)*100)}%`;$('mpText').textContent=`${Math.floor(s.mp)} / ${50+(s.int-10)*4}`;$('mpBar').style.width=`${s.mp/(50+(s.int-10)*4)*100}%`;
$('enemyName').textContent=enemy.name;$('enemyType').textContent=`${enemy.boss?'FLOOR BOSS':'FLOOR GUARDIAN'} · LV. ${enemy.level}`;$('enemyHpText').textContent=`${Math.ceil(enemy.hp)} / ${enemy.max}`;$('enemyBar').style.width=`${Math.max(0,enemy.hp/enemy.max*100)}%`;$('goldText').textContent=`◈ ${s.gold}`;$('potionCount').textContent=`${s.potions} IN PACK`;$('weaponName').textContent=['Iron Longsword','Knightfall','Starforged Edge','Worldsplitter'][s.weapon];$('weaponBonus').textContent=`+${4+s.weapon*7} attack`;
$('floorStatus').textContent=combatState==='fight'?'HUNT IN PROGRESS':combatState==='clear'?'FLOOR CLEARED':'TOWER CONQUERED';$('continueBtn').classList.toggle('hidden',combatState!=='clear');$('nextFloor').textContent=String(s.floor+1).padStart(2,'0');$('attackBtn').disabled=combatState!=='fight'||attackCd>0;$('skillBtn').disabled=combatState!=='fight'||skillCd>0||s.mp<12;$('dodgeBtn').disabled=combatState!=='fight'||dodgeCd>0;$('potionBtn').disabled=s.potions<1||s.hp>=100+(s.vit-10)*8;
$('attackCd').style.width=`${attackCd/0.55*100}%`;$('skillCd').style.width=`${skillCd/1.5*100}%`;$('dodgeCd').style.width=`${dodgeCd/2.5*100}%`;$('questTitle').textContent=isBoss()?'Slay the Floor Boss':`First Blood · Floor ${s.floor}`;$('questDesc').textContent=combatState==='clear'?'Guardian defeated. The path upward is open.':`Defeat ${enemy.boss?'the guardian':'the guardian'} of Floor ${s.floor}.`;$('questProgress').textContent=combatState==='clear'?'1 / 1':'0 / 1';$('questBar').style.width=combatState==='clear'?'100%':'0%';$('questReward').textContent=100+s.floor*20;$('goldReward').textContent=30+s.floor*8;
let list=$('floorList');list.innerHTML='';for(let i=0;i<20;i++){let floor=Math.floor((s.floor-1)/5)*5+i+1,seg=document.createElement('i');if(floor<s.floor)seg.className='done';if(floor===s.floor)seg.className='current';list.append(seg)} }
function addXp(n){s.xp+=n;while(s.xp>=xpNeed()){s.xp-=xpNeed();s.level++;s.points+=3;s.hp=100+(s.vit-10)*8;s.mp=50+(s.int-10)*4;log(`<b>LEVEL UP!</b> You are now level ${s.level}. +3 stat points.`, 'gold');toast(`LEVEL UP · ${s.level}`)} }
