 function attack(power=1,magic=false){if(combatState!=='fight')return;if(magic){if(s.mp<12||skillCd>0)return;s.mp-=12;skillCd=1.5}else{if(attackCd>0)return;attackCd=.55}playerAnim=magic?-.55:-.35;enemy.flash=.18;let damage=Math.round((s.str*2+4+s.weapon*7+(magic?s.int*2:0))*(.85+Math.random()*.3)*power);enemy.hp-=damage;burst(canvas.width*.68,canvas.height*.58,magic?'#8ce9ff':'#ffe0a0',magic?22:12);log(`${magic?'<b>ARCANE BURST</b>':`You strike`} for <span class="damage">${damage}</span> damage.`);audioHit(magic?440:170);if(enemy.hp<=0){enemy.hp=0;updateUI();onKill();return}if(magic){enemy.stun=.45;toast('ARCANE BURST')}updateUI()}
 function dodge(){if(combatState!=='fight'||dodgeCd>0)return;dodgeCd=2.5;invuln=.8;playerAnim=.45;burst(canvas.width*.37,canvas.height*.7,'#8bdac8',9);log('<b>Perfect timing.</b> You evade into the shadows.','good');audioHit(330)}

